CREATE OR REPLACE FUNCTION public.claim_initial_admin(_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN PERFORM pg_advisory_xact_lock(7102026); IF EXISTS (SELECT 1 FROM public.user_roles WHERE role='admin') THEN RAISE EXCEPTION 'تم إعداد المشرف مسبقاً'; END IF; IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id=_user_id) THEN RAISE EXCEPTION 'الحساب غير موجود'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES (_user_id,'admin'); END $$;
REVOKE ALL ON FUNCTION public.claim_initial_admin(uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.claim_initial_admin(uuid) TO service_role;
REVOKE EXECUTE ON FUNCTION public.audit_trigger(), public.handle_new_user(), public.touch_updated_at() FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.review_swap(_request_id uuid,_approve boolean,_note text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE r public.swap_requests; s public.shifts; t public.shifts; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'هذه العملية للمشرف فقط'; END IF; SELECT * INTO r FROM public.swap_requests WHERE id=_request_id FOR UPDATE; IF NOT FOUND OR r.status <> 'pending' THEN RAISE EXCEPTION 'الطلب غير متاح للمراجعة'; END IF; IF _approve THEN PERFORM id FROM public.shifts WHERE id IN (r.requester_shift_id,r.target_shift_id) ORDER BY id FOR UPDATE; SELECT * INTO s FROM public.shifts WHERE id=r.requester_shift_id; IF s.member_id IS DISTINCT FROM r.requester_id THEN RAISE EXCEPTION 'تغير إسناد المناوبة، أرسل طلباً جديداً'; END IF; IF r.target_shift_id IS NOT NULL THEN SELECT * INTO t FROM public.shifts WHERE id=r.target_shift_id; IF t.member_id IS DISTINCT FROM r.target_member_id OR t.id=s.id THEN RAISE EXCEPTION 'تغيرت المناوبة المقابلة'; END IF; END IF; UPDATE public.shifts SET member_id=r.target_member_id,assignee_label=(SELECT full_name FROM public.profiles WHERE id=r.target_member_id) WHERE id=s.id; IF r.target_shift_id IS NOT NULL THEN UPDATE public.shifts SET member_id=r.requester_id,assignee_label=(SELECT full_name FROM public.profiles WHERE id=r.requester_id) WHERE id=t.id; END IF; END IF; UPDATE public.swap_requests SET status=CASE WHEN _approve THEN 'approved'::public.swap_status ELSE 'rejected'::public.swap_status END,reviewed_by=auth.uid(),reviewed_at=now(),review_note=left(_note,1000) WHERE id=r.id; END $$;
REVOKE ALL ON FUNCTION public.review_swap(uuid,boolean,text), public.cancel_swap(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_swap(uuid,boolean,text), public.cancel_swap(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.import_schedule(_rows jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE r jsonb; inserted integer:=0; d date; m uuid; t uuid; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'المشرف فقط'; END IF; IF jsonb_typeof(_rows) <> 'array' OR jsonb_array_length(_rows)>2000 THEN RAISE EXCEPTION 'ملف غير صالح أو كبير جداً'; END IF; PERFORM pg_advisory_xact_lock(7102027); FOR r IN SELECT value FROM jsonb_array_elements(_rows) LOOP d:=(r->>'date')::date; m:=(r->>'memberId')::uuid; t:=(r->>'typeId')::uuid; IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id=m) OR NOT EXISTS (SELECT 1 FROM public.shift_types WHERE id=t) THEN RAISE EXCEPTION 'عضو أو نوع مناوبة غير موجود'; END IF; IF NOT EXISTS (SELECT 1 FROM public.shifts WHERE shift_date=d AND member_id=m AND shift_type_id=t) THEN INSERT INTO public.shifts(shift_date,member_id,assignee_label,shift_type_id,source,created_by) SELECT d,m,full_name,t,'import',auth.uid() FROM public.profiles WHERE id=m; inserted:=inserted+1; END IF; END LOOP; RETURN inserted; END $$;
REVOKE ALL ON FUNCTION public.import_schedule(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.import_schedule(jsonb) TO authenticated;
GRANT SELECT ON public.audit_log TO authenticated; GRANT ALL ON public.audit_log TO service_role;
ALTER PUBLICATION supabase_realtime ADD TABLE public.profiles, public.user_roles, public.audit_log;